import { NextRequest, NextResponse } from "next/server";
import { userDb } from "@/lib/firestoreDb";
import bcrypt from "bcryptjs";

export async function GET() {
  try {
    console.log("Fetching all users from Firestore...");
    let users;
    try {
      users = await userDb.getAll();
    } catch (queryError: any) {
      // If users collection doesn't exist, return empty array
      if (queryError.code === 5 || queryError.message?.includes("NOT_FOUND")) {
        console.log("Users collection not found, returning empty users array");
        return NextResponse.json({ users: [] });
      }
      throw queryError;
    }
    console.log(`Successfully fetched ${users.length} users`);
    return NextResponse.json({ users });
  } catch (error: any) {
    console.error("Users load error:", {
      message: error?.message,
      code: error?.code,
      details: error?.details,
      fullError: error,
    });
    return NextResponse.json(
      {
        error: "Failed to load users",
        details: error?.message || "Unknown error",
      },
      { status: 500 },
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const payload = await request.json();

    // Validate required fields
    if (!payload.email) {
      return NextResponse.json({ error: "Email is required" }, { status: 400 });
    }

    // Check if user already exists
    const existingUser = await userDb.getByEmail(payload.email);
    if (existingUser) {
      return NextResponse.json(
        { error: "User with this email already exists" },
        { status: 409 },
      );
    }

    const rolesArray = payload.roles || [payload.role || "faculty"];

    // Hash password if provided
    let hashedPassword = undefined;
    if (payload.password) {
      hashedPassword = await bcrypt.hash(payload.password, 10);
    }

    const newUser = await userDb.create({
      name: payload.name ?? payload.username ?? payload.email,
      email: payload.email,
      emailVerified: payload.emailVerified ?? false,
      phone: payload.phone,
      department: payload.department,
      image: payload.image,
      role: payload.role ?? "faculty",
      roles: rolesArray,
      approved: payload.approved ?? false,
      banned: payload.banned ?? false,
      banReason: payload.banReason,
      banExpires: payload.banExpires ? new Date(payload.banExpires) : undefined,
      password: hashedPassword,
      firebaseUid: payload.firebaseUid,
    });

    // Fetch all users to return updated list
    const users = await userDb.getAll();
    return NextResponse.json({ users, newUser });
  } catch (error) {
    console.error("User create error:", error);
    return NextResponse.json(
      { error: "Failed to create user" },
      { status: 500 },
    );
  }
}
